Voici un exemple de code pour un bot Discord avec une commande "bannir" à l'aide de Discord.js v14 :

1. Installez les dépendances nécessaires en exécutant la commande suivante dans votre terminal :

```
npm install discord.js dotenv
```

2. Créez un fichier `.env` et ajoutez votre clé de bot Discord :

```
DISCORD_TOKEN=<VotreCléDeBot>
```

3. Créez un nouveau fichier appelé `index.js` et collez le code suivant :

```javascript
// Importez les modules nécessaires
const { Client, GatewayIntentBits } = require('discord.js');
require('dotenv').config();

// Connexion du client Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Événement de connexion du client Discord
client.on('ready', () => {
  console.log(`Bot ${client.user.username} connecté`);
});

// Commande "bannir"
client.commands = new Map();
client.commands.set('ban', require('./commands/ban'));

// Événement de commande slash
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const command = client.commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'Une erreur est survenue, veuillez réessayer plus tard.', ephemeral: true });
  }
});

// Connexion du client Discord
client.login(process.env.DISCORD_TOKEN);
```

4. Créez un nouveau dossier appelé `commands` et ajoutez un nouveau fichier appelé `ban.js`. Ajoutez le code suivant :

```javascript
const { MessageEmbed } = require('discord.js');

module.exports = {
  name: 'ban',
  description: 'Bannir un membre du serveur',

  execute: async (interaction) => {
    const member = interaction.options.getMember('membre');

    if (!member) {
      return interaction.reply({ content: 'Veuillez spécifier un membre à bannir.', ephemeral: true });
    }

    if (member.permissions.has('ADMINISTRATOR') || interaction.member.permissions.has('ADMINISTRATOR')) {
      return interaction.reply({ content: 'Vous ne pouvez pas bannir un administrateur.', ephemeral: true });
    }

    await member.ban({ reason: `Bannissement effectué par ${interaction.user.tag}` });

    const embed = new MessageEmbed()
      .setTitle('Membre banni')
      .addField('Membre banni', `${member.user.tag} (${member.user.id})`)
      .addField('Raison du bannissement', 'Bannissement effectué par une commande.')
      .setFooter({ text: `Bannissement effectué par ${interaction.user.tag}` });

    await interaction.reply({ embeds: [embed] });
  },
};
```

