Voici une fonction C++ qui convertit un texte au format Markdown en HTML :

```cpp
#include <string>
#include <iostream>
#include <sstream>
#include <regex>

std::string markdown_to_html(const std::string& markdown) {
    std::stringstream ss;
    std::string line;

    // Markdown headers
    std::regex header_regex("^#{1,6}(.+?)\\s*$");
    std::smatch header_match;

    while (std::getline(std::stringstream(markdown), line)) {
        if (std::regex_match(line, header_match, header_regex)) {
            int level = header_match.prefix().length();
            ss << "<h" << level << ">" << header_match[1] << "</h" << level << ">\n";
        } else {
            ss << line << "\n";
        }
    }

    // Markdown inline styles
    std::regex italic_regex("\\*([^*]*)\\*");
    std::regex bold_regex("__([^_]+)__");
    std::regex underline_regex("~~([^~]+)~~");
    std::regex strikethrough_regex("~~~([^~]+)~~~");
    std::regex code_regex("`([^`]+)`");

    while (std::getline(ss, line)) {
        std::stringstream ss_line(line);
        std::string token;

        while (std::getline(ss_line, token, ' ')) {
            std::string new_token;

            if (std::regex_match(token, italic_regex)) {
                new_token = "<i>" + std::regex_replace(token, italic_regex, "$1") + "</i>";
            } else if (std::regex_match(token, bold_regex)) {
                new_token = "<b>" + std::regex_replace(token, bold_regex, "$1") + "</b>";
            } else if (std::regex_match(token, underline_regex)) {
                new_token = "<u>" + std::regex_replace(token, underline_regex, "$1") + "</u>";
            } else if (std::regex_match(token, strikethrough_regex)) {
                new_token = "<s>" + std::regex_replace(token, strikethrough_regex, "$1") + "</s>";
            } else if (std::regex_match(token, code_regex)) {
                new_token = "<code>" + std::regex_replace(token, code_regex, "$1") + "</code>";
            } else {
                new_token = token;
            }

            if (!ss_line.eof()) {
                ss << " " << new_token;
            } else {
                ss << new_token;
            }
        }
        ss << "\n";
    }

    return ss.str();
}

int main() {
    std::string markdown = "## H1\n"
                           "### H2\n"
                           "#### H3\n\n"
                           "*italic*\n"
                           "**bold**\n"
                           "__underline__\n"
                           "~~strikethrough~~\n"
                           "`code`";

    std::string html = markdown_to_html(markdown);

    std::cout << html << std::endl;

    return 0;
}
```

Cela convertira les en-têtes Markdown en balises HTML `<h1>`, `<h2>`, etc., et les styles inline en balises HTML correspondantes. Cette fonction ne prend en compte que les styles les plus courants. Pour une conversion plus complète, vous pouvez utiliser une bibliothèque comme [Pandoc](https://pandoc.org/) ou [Markdown::Parser](https://metacpan.org/release/Markdown-Parser).

