```c
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600

typedef struct {
    SDL_Point *body;
    int length;
    SDL_Point direction;
} Snake;

void snake_init(Snake *snake, SDL_Point start_pos, int length);
void snake_draw(Snake *snake, SDL_Renderer *renderer);
void snake_move(Snake *snake);
int snake_collision(Snake *snake, SDL_Point food_pos);
void snake_increase_length(Snake *snake);
