5. Créez un nouveau fichier nommé "snake.c" et ajoutez les définitions suivantes :

```c
#include "snake.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void snake_init(Snake *snake, SDL_Point start_pos, int length) {
    snake->body = (SDL_Point*)malloc(length * sizeof(SDL_Point));
    memcpy(snake->body, &start_pos, sizeof(SDL_Point));
    snake->length = length;
    snake->direction.x = 1;
    snake->direction.y = 0;
}

void snake_draw(Snake *snake, SDL_Renderer *renderer) {
    SDL_SetRenderDrawColor(renderer, 0, 0, 255, 255);
    for (int I = 0; I < snake->length; i++) {
        SDL_RenderFillRect(renderer, (SDL_Rect*)(&(snake->body[i])));
    }
}

void snake_move(Snake *snake) {
    for (int I = snake->length - 1; I > 0; i--) {
        snake->body[i] = snake->body[i - 1];
    }
    snake->body[0].x += snake->direction.x;
    snake->body[0].y += snake->direction.y;
}

int snake_collision(Snake *snake, SDL_Point food_pos) {
    if (snake->body[0].x == food_pos.x && snake->body[0].y == food_pos.y) {
        return 1;
    }
    for (int I = 1; I < snake->length; i++) {
        if (snake->body[0].x == snake->body[i].x && snake->body[0].y == snake->body[i].y) {
            return 0;
        }
    }
    return 1;
}

void snake_increase_length(Snake *snake) {
    SDL_Point *new_tail = (SDL_Point*)realloc(snake->body, (snake->length + 1) * sizeof(SDL_Point));
    if (new_tail != NULL) {
        snake->body = new_tail;
        memcpy(&(snake->body[snake->length]), &(snake->body[snake->length - 1]), sizeof(SDL_Point));
        snake->length++;
    }
}

void snake_reset(Snake *snake) {
    free(snake->body);
    snake_init(snake, (SDL_Point){ 100, 100 }, 3);
}
```

6. Créez un nouveau fichier nommé "main.c" et ajoutez le code suivant :

```c
#include "snake.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>

int main(int argc, char *argv[]) {
    SDL_Window *window;
    SDL_Renderer *renderer;

    SDL_Init(SDL_INIT_VIDEO);
    IMG_Init(IMG_INIT_PNG);

    window = SDL_CreateWindow("Snake",
                               SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                               WINDOW_WIDTH, WINDOW_HEIGHT,
                               SDL_WINDOW_SHOWN);

    renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    SDL_Surface *background_surface = IMG_Load("background.png");
    SDL_Texture *background_texture = SDL_CreateTextureFromSurface(renderer, background_surface);
    SDL_FreeSurface(background_surface);

    Snake snake;
    snake_init(&snake, (SDL_Point){ 200, 200 }, 3);

    SDL_Point food_pos = (SDL_Point){ 650, 400 };

    int score = 0;

    bool running = true;
    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            switch (event.type) {
                case SDL_QUIT:
                    running = false;
                    break;
                case SDL_KEYDOWN:
                    switch (event.key.keysym.sym) {
                        case SDLK_LEFT:
                            if (snake.direction.x != 1) {
                                snake.direction.x = -1;
                                snake.direction.y = 0;
                            }
                            break;
                        case SDLK_RIGHT:
                            if (snake.direction.x != -1) {
                                snake.direction.x = 1;
                                snake.direction.y = 0;
                            }
                            break;
                        case SDLK_UP:
                            if (snake.direction.y != 1) {
                                snake.direction.x = 0;
                                snake.direction.y = -1;
                            }
                            break;
                        case SDLK_DOWN:
                            if (snake.direction.y != -1) {
                                snake.direction.x = 0;
                                snake.direction.y = 1;
                            }
                            break;
                    }
                    break;
            }
        }

        SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
        SDL_RenderClear(renderer);

        SDL_SetTextureColorMod(background_texture, 255, 255, 255);
        SDL_RenderCopy(renderer, background_texture, NULL, NULL);

        snake_move(&snake);

        if (snake_collision(&snake, food_pos)) {
            score++;
            snake_increase_length(&snake);
            food_pos.x = rand() % (WINDOW_WIDTH - 50) + 25;
            food_pos.y = rand() % (WINDOW_HEIGHT - 50) + 25;
        }

        snake_draw(&snake, renderer);

        char score_text[64];
        sprintf(score_text, "Score: %d", score);
        SDL_SetTextureColorMod(background_texture, 0, 0, 0);
        SDL_RenderCopy(renderer, background_texture, NULL, NULL);
        SDL_SetTextureColorMod(background_texture, 255, 255, 255);
        SDL_Rect score_rect = { WINDOW_WIDTH / 2 - 50, 10, 0, 0 };
        SDL_QueryTexture(background_texture, NULL, NULL, &score_rect.w, &score_rect.h);
        SDL_RenderCopy(renderer, background_texture, NULL, &score_rect);
        SDL_SetTextureColorMod(background_texture, 255, 255, 255);
        SDL_Rect score_rect2 = { WINDOW_WIDTH / 2 - 100, 10, 0, 0 };
        SDL_QueryTexture(background_texture, NULL, NULL, &score_rect2.w, &score_rect2.h);
        SDL_RenderCopy(renderer, renderer, NULL, &score_rect2);
        SDL_SetTextureColorMod(background_texture, 0, 0, 0);
        SDL_Rect score_rect3 = { WINDOW_WIDTH / 2 - 100 + 10, 10, 0, 0 };
        SDL_QueryTexture(background_texture, NULL, NULL, &score_rect3.w, &score_rect3.h);
        SDL_RenderCopy(renderer, renderer, NULL, &score_rect3);
        SDL_SetTextureColorMod(background_texture, 255, 255, 255);
        SDL_Rect score_rect4 = { WINDOW_WIDTH / 2 - 100 + 20, 10, 0, 0 };
        SDL_QueryTexture(background_texture, NULL, NULL, &score_rect4.w, &score_rect4.h);
        SDL_RenderCopy(renderer, renderer, NULL, &score_rect4);
        SDL_RenderCopy(renderer, renderer, NULL, &score_rect);
        SDL_RenderCopy(renderer, renderer, NULL, &score_rect2);
        SDL_RenderCopy(renderer, renderer, NULL, &score_rect3);
        SDL_RenderCopy(renderer, renderer, NULL, &score_rect4);
        SDL_SetTextureColorMod(background_texture, 255, 255, 255);

        SDL_RenderPresent(renderer);

        SDL_Delay(20);
    }

    SDL_DestroyTexture(background_texture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);

    SDL_Quit();

    return 0;
}
```

